+<?php
+
+namespace App\Http\Controllers\Student;
+
+use App\Enums\AppointmentStatus;
+use App\Enums\Role;
+use App\Http\Controllers\Controller;
+use App\Models\Appointment;
+use App\Models\User;
+use Illuminate\Http\RedirectResponse;
+use Illuminate\Http\Request;
+use Illuminate\View\View;
+
+class AppointmentController extends Controller
+{
+    /**
+     * Display a listing of the student's appointments.
+     */
+    public function index(Request $request): View
+    {
+        $appointments = $request->user()
+            ->hasMany(Appointment::class, 'student_id')
+            ->with('counselor')
+            ->orderBy('scheduled_at', 'desc')
+            ->paginate(10);
+
+        return view('student.appointments.index', compact('appointments'));
+    }
+
+    /**
+     * Show the form for creating a new appointment.
+     */
+    public function create(Request $request): View
+    {
+        // Get counselors assigned to student's college or all active counselors
+        $counselors = User::where('role', Role::Counselor)
+            ->where('is_active', true)
+            ->get();
+
+        return view('student.appointments.create', compact('counselors'));
+    }
+
+    /**
+     * Store a newly created appointment in storage.
+     */
+    public function store(Request $request): RedirectResponse
+    {
+        $validated = $request->validate([
+            'counselor_id' => ['nullable', 'exists:users,id'],
+            'scheduled_at' => ['required', 'date', 'after:now'],
+            'purpose' => ['required', 'string', 'max:255'],
+            'notes' => ['nullable', 'string', 'max:1000'],
+        ]);
+
+        $request->user()->hasMany(Appointment::class, 'student_id')->create([
+            'counselor_id' => $validated['counselor_id'] ?? null,
+            'scheduled_at' => $validated['scheduled_at'],
+            'purpose' => $validated['purpose'],
+            'notes' => $validated['notes'] ?? null,
+            'status' => AppointmentStatus::Pending,
+        ]);
+
+        return redirect()->route('student.appointments.index')
+            ->with('status', 'Appointment request submitted successfully.');
+    }
+
+    /**
+     * Cancel a pending appointment.
+     */
+    public function cancel(Request $request, Appointment $appointment): RedirectResponse
+    {
+        if ($appointment->student_id !== $request->user()->id) {
+            abort(403);
+        }
+
+        if ($appointment->status !== AppointmentStatus::Pending) {
+            return back()->with('error', 'Only pending appointments can be cancelled.');
+        }
+
+        $appointment->update([
+            'status' => AppointmentStatus::Cancelled,
+        ]);
+
+        return redirect()->route('student.appointments.index')
+            ->with('status', 'Appointment cancelled.');
+    }
+}
